//! Newtype identifiers, generated by [`newtype_ids!`](crate::newtype_ids).

newtype_ids! {
    /// Identifier of a schema entry; assigned by [`Schema::insert`](crate::schema::Schema::insert).
    SettingId => "setting#",
    /// Identifier of a group of settings inside a schema.
    GroupId => "group#",
    /// Identifier of a registered command.
    CommandId => "command#",
}

#[cfg(test)]
mod tests {
    use super::{CommandId, GroupId, SettingId};

    #[test]
    fn unassigned_is_recognised() {
        assert!(SettingId::unassigned().is_unassigned());
        assert!(!SettingId::new(3).is_unassigned());
    }

    #[test]
    fn index_round_trips() {
        let id = SettingId::from(17);
        assert_eq!(id.get(), 17);
        assert_eq!(id, SettingId::new(17));
    }

    #[test]
    fn identifiers_render_with_their_label() {
        assert_eq!(SettingId::new(2).to_string(), "setting#2");
        assert_eq!(GroupId::new(0).to_string(), "group#0");
        assert_eq!(CommandId::label(), "command#");
    }

    #[test]
    fn identifiers_are_ordered_by_index() {
        let mut ids = vec![SettingId::new(4), SettingId::new(1), SettingId::new(3)];
        ids.sort();
        assert_eq!(
            ids,
            vec![SettingId::new(1), SettingId::new(3), SettingId::new(4)]
        );
        assert!(SettingId::new(1) < SettingId::new(2));
    }
}
